import { Router } from 'express';
import { fail, route, integer } from './errors.js';
export function catalogRoutes(store) {
  const router = Router();
  router.get('/products',route(async(req,res) => {
    const {category,q,page='1',pageSize='12'} = req.query;
    if ((category !== undefined && typeof category !== 'string') || (q !== undefined && typeof q !== 'string') || !/^[0-9]+$/.test(page) || !/^[0-9]+$/.test(pageSize)) fail(400,'INVALID_INPUT','Invalid catalog query');
    const current = integer(Number(page),1,Number.MAX_SAFE_INTEGER,'page');
    const size = integer(Number(pageSize),1,50,'pageSize');
    let items = await store.read('products');
    if (category !== undefined) items = items.filter(p => p.category === category);
    if (q) items = items.filter(p => (p.name+' '+p.description).toLowerCase().includes(q.toLowerCase()));
    items.sort((a,b) => a.name.localeCompare(b.name));
    res.json({items:items.slice((current-1)*size,current*size),page:current,pageSize:size,total:items.length});
  }));
  router.get('/products/:id',route(async(req,res) => { const product = (await store.read('products')).find(p=>p.id===req.params.id); if(!product) fail(404,'NOT_FOUND','Product not found'); res.json(product); }));
  router.get('/categories',route(async(req,res) => { const counts = new Map(); for(const p of await store.read('products')) counts.set(p.category,(counts.get(p.category)||0)+1); res.json({items:[...counts].sort(([a],[b])=>a.localeCompare(b)).map(([name,count])=>({name,count}))}); }));
  return router;
}

export function fail(status, code, message) { const error = new Error(message); error.status = status; error.code = code; throw error; }
export const route = fn => (req,res,next) => Promise.resolve().then(() => fn(req,res)).catch(next);
export function integer(value, min, max, field) { if (!Number.isSafeInteger(value) || value < min || value > max) fail(400,'INVALID_INPUT',field + ' is out of range'); return value; }

import express from 'express';
import { Store } from './store.js';
import { catalogRoutes } from './catalog.js';
export function createApp({ dataDir = new URL('../data/', import.meta.url).pathname } = {}) {
  const app = express();
  const store = new Store(dataDir);
  app.use(express.json());
  app.get('/health', (req, res) => res.json({ status: 'ok' }));
  app.use('/api', catalogRoutes(store));
  app.use((req, res) => res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Route not found' } }));
  app.use((error, req, res, next) => res.status(error.status || 400).json({ error: { code: error.code || 'INVALID_INPUT', message: error.message } }));
  return app;
}

import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
export class Store {
  constructor(dir) { this.dir = dir; this.tail = Promise.resolve(); }
  async read(name) { try { return JSON.parse(await readFile(join(this.dir,name + '.json'),'utf8')); } catch(error) { if (error.code === 'ENOENT' && name === 'orders') return []; throw error; } }
  async write(name, value) { await mkdir(this.dir,{recursive:true}); const path = join(this.dir,name+'.json'); const temp = path+'.'+randomUUID()+'.tmp'; await writeFile(temp, JSON.stringify(value,null,2)+'\n'); await rename(temp,path); }
  async exclusive(fn) { const previous = this.tail; let release; this.tail = new Promise(resolve => { release = resolve; }); await previous; try { return await fn(); } finally { release(); } }
}
